design_text:
{
  "site_summary": "A full-sun balcony with moderate moisture and no pets in the household.",
  "layout_strategy": "The planting is structured vertically with lush trailing vines spilling from high wall brackets, mid-level upright shrubs creating a fragrant backdrop against the wall, and low texturing groundcovers anchoring the containers at floor level.",
  "combination_logic": "The scheme combines fine-textured trailing foliage with bold, architectural flower plumes and woody aromatic shrubs, offering a sensory experience of citrus scent and tactile contrasts that intensifies during the sunny summer months.",
  "zones": [
    {
      "zone_name": "Trailing Canopy",
      "zone_role": "hanging",
      "layer": "vertical",
      "placement": "On high wall-mounted brackets, receiving 6 hours of full afternoon sun.",
      "plants": [
        {
          "scientific_name": "Pilea nummulariifolia",
          "common_name": "Creeping Charlie",
          "why": "Provides a lush trailing habit for the upper vertical layer.",
          "role_in_combination": "Contributes soft, rounded leaf textures that contrast sharply with the upright spires below."
        }
      ],
      "maintenance": [
        "Water thoroughly when the top inch of soil feels dry.",
        "Feed with a balanced liquid fertilizer monthly during the growing season.",
        "Trim back unruly stems in late summer to maintain shape."
      ]
    },
    {
      "zone_name": "Fragrant Backdrop",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "In large containers against the main back wall, receiving full sun all day.",
      "plants": [
        {
          "scientific_name": "Aloysia triphylla",
          "common_name": "Lemon Verbena",
          "why": "Delivers intense citrus fragrance and a woody shrub structure.",
          "role_in_combination": "Serves as the primary scent anchor, releasing lemon aromas when brushed against."
        },
        {
          "scientific_name": "Stephanotis floribunda",
          "common_name": "Madagascar Jasmine",
          "why": "Adds height and highly scented white tubular blooms.",
          "role_in_combination": "Provides vertical structure and seasonal floral contrast against the Lemon Verbena foliage."
        }
      ],
      "maintenance": [
        "Keep soil evenly moist, watering deeply every few days in peak summer.",
        "Prune back woody stems in early spring to encourage fresh lateral growth.",
        "Repot every two years into fresh, nutrient-rich compost."
      ]
    },
    {
      "zone_name": "Color Accent Edge",
      "zone_role": "focal",
      "layer": "ground",
      "placement": "In low bowls along the floor edge, basking in full sun.",
      "plants": [
        {
          "scientific_name": "Celosia plumosa",
          "common_name": "Celosia Plumosa",
          "why": "Introduces vivid, feathery plumes of color at the base of the larger pots.",
          "role_in_combination": "Provides bright chromatic contrast and unusual velvety textures at eye-to-knee level."
        }
      ],
      "maintenance": [
        "Water at the base daily during hot summer dry spells.",
        "Deadhead spent flower plumes to encourage continuous blooming.",
        "Replace annually as it is a tender seasonal plant."
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all containers",
      "frequency": "Daily in peak summer, twice weekly in spring and autumn",
      "season": "Summer"
    },
    {
      "task": "Apply a balanced liquid fertilizer to support heavy blooming",
      "frequency": "Every two weeks",
      "season": "Spring and Summer"
    },
    {
      "task": "Prune back tender perennials and clear out spent annuals",
      "frequency": "Once at the end of the season",
      "season": "Autumn"
    }
  ],
  "care_cautions": [
    "The trailing Pilea nummulariifolia in the upper hanging baskets can experience root rot if allowed to sit in standing water during prolonged rainy periods.",
    "The full sun exposure on the balcony can cause rapid soil dry-out for the Celosia plumosa bowls, leading to wilting if not watered consistently."
  ],
  "pet_safety_note": "Since there are no pets in the household, all selected plants can be enjoyed purely for their sensory and aesthetic qualities without restriction."
}
